<style>
    *,
    *::before,
    *::after {
        box-sizing: border-box;
    }

    body {
        background: #f5f5f5;
        padding-bottom: 90px;
    }

    main {
        padding: 0;
    }

    /* ─── Step Bar ─── */
    .step-bar {
        background: #fff;
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        padding: 14px 24px 10px;
        position: relative;
        border-bottom: 1px solid #eee;
    }

    .step-bar::after {
        content: '';
        position: absolute;
        top: 28px;
        left: 12%;
        width: 76%;
        height: 1.5px;
        background: #e0e0e0;
        z-index: 0;
    }

    .step {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 4px;
        z-index: 1;
    }

    .step-dot {
        width: 30px;
        height: 30px;
        border-radius: 50%;
        border: 2px solid #ccc;
        background: #fff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 12px;
        font-weight: 700;
        color: #bbb;
    }

    .step.done .step-dot {
        border-color: #9f2089;
        color: #9f2089;
        background: #fdf3fc;
    }

    .step.active .step-dot {
        border-color: #9f2089;
        color: #9f2089;
        border-width: 2.5px;
    }

    .step-lbl {
        font-size: 11px;
        color: #aaa;
        font-weight: 600;
    }

    .step.done .step-lbl,
    .step.active .step-lbl {
        color: #9f2089;
        font-weight: 700;
    }

    /* ─── Payment Header ─── */
    .pay-header {
        background: #fff;
        margin-top: 6px;
        padding: 14px 16px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        border-bottom: 1px solid #f0f0f0;
    }

    .pay-header h2 {
        font-size: 1rem;
        font-weight: 800;
        color: #111;
        margin: 0;
    }

    .safe-badge {
        display: flex;
        align-items: center;
        gap: 4px;
        font-size: 10px;
        color: #555;
        font-weight: 700;
        text-align: right;
        line-height: 1.3;
    }

    .safe-badge svg {
        flex-shrink: 0;
    }

    /* ─── Offer Banner ─── */
    .offer-banner {
        width: 100%;
        display: block;
    }

    .offer-banner img {
        width: 100%;
        height: auto;
        display: block;
    }

    /* ─── Pay Online Section ─── */
    .section-card {
        background: #fff;
        margin-top: 8px;
    }

    .section-title {
        padding: 12px 16px;
        font-size: 0.82rem;
        font-weight: 800;
        color: #222;
        letter-spacing: .5px;
        border-bottom: 1px solid #f0f0f0;
    }

    .upi-header {
        padding: 12px 16px;
        display: flex;
        align-items: center;
        gap: 8px;
        border-bottom: 1px solid #f0f0f0;
    }

    .upi-badge {
        background: #16a34a;
        color: #fff;
        font-size: 10px;
        font-weight: 700;
        padding: 2px 6px;
        border-radius: 4px;
    }

    .upi-header span {
        font-size: 0.9rem;
        font-weight: 600;
        color: #222;
    }

    /* ─── Payment Method Row ─── */
    .method-row {
        padding: 14px 16px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        border-bottom: 1px solid #f0f0f0;
        cursor: pointer;
    }

    .method-left {
        display: flex;
        align-items: center;
        gap: 12px;
    }

    .radio-wrap {
        width: 20px;
        height: 20px;
        border-radius: 50%;
        border: 2px solid #ccc;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }

    .radio-wrap.selected {
        border-color: #9f2089;
    }

    .radio-inner {
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: #9f2089;
        display: none;
    }

    .radio-wrap.selected .radio-inner {
        display: block;
    }

    .method-name {
        font-size: 0.9rem;
        color: #333;
    }

    .method-icon {
        width: 36px;
        height: 36px;
        object-fit: contain;
    }

    /* ─── Price Summary ─── */
    .price-card {
        background: #fff;
        margin-top: 8px;
        padding: 16px;
    }

    .price-row {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 7px 0;
        font-size: 0.88rem;
    }

    .price-row .lbl {
        font-weight: 600;
        color: #555;
    }

    .price-row .val {
        color: #111;
    }

    .price-row .free {
        color: #16a34a;
        font-weight: 700;
    }

    .price-divider {
        height: 1px;
        background: #efefef;
    }

    .price-row.total .lbl,
    .price-row.total .val {
        font-weight: 800;
        color: #111;
        font-size: 0.92rem;
    }

    /* ─── Sticky Footer ─── */
    .sticky-footer {
        position: fixed;
        bottom: 0;
        left: 0;
        right: 0;
        background: #fff;
        border-top: 1px solid #eee;
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 12px 16px;
        z-index: 999;
    }

    .footer-amount {
        font-size: 1.1rem;
        font-weight: 800;
        color: #111;
        line-height: 1.2;
    }

    .footer-detail {
        font-size: 10px;
        color: #9f2089;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: .3px;
        cursor: pointer;
    }

    .pay-btn {
        background: #9f2089;
        color: #fff;
        border: none;
        border-radius: 8px;
        padding: 13px 28px;
        font-size: 0.95rem;
        font-weight: 700;
        cursor: pointer;
    }

    .pay-btn:active {
        opacity: .85;
    }

    .cod-unavailable {
        margin-top: 8px;
        background: #fff;
        padding: 14px 16px;
        border-left: 4px solid #d32f2f;
        font-size: 0.88rem;
        font-weight: 700;
        color: #d32f2f;
    }

    /* ─── Screenshot-style Payment Options ─── */
    .section-card {
        margin: 8px 10px 0;
        border-radius: 4px;
        background: transparent;
    }
    .section-title {
        background: #fff;
        padding: 10px 2px 8px;
        border: 0;
        font-size: .82rem;
    }
    .upi-header { display: none; }
    .method-row {
        background: #fff;
        margin-bottom: 6px;
        padding: 12px 10px;
        border: 1px solid #e5e5e5;
        border-radius: 5px;
        min-height: 58px;
    }
    .method-left { gap: 10px; flex: 1; }
    .method-icon { width: 34px; height: 34px; order: 2; }
    .method-info {
        display: flex;
        flex-direction: column;
        gap: 2px;
        order: 3;
        flex: 1;
    }
    .method-name { font-size: .84rem; font-weight: 700; color: #222; }
    .method-sub { font-size: .64rem; color: #777; font-weight: 500; }
    .offer-tag {
        margin-left: 8px;
        padding: 4px 7px;
        border-radius: 4px;
        background: #fde7f7;
        color: #d21888;
        font-size: .62rem;
        font-weight: 800;
        white-space: nowrap;
    }
    .offer-tag.purple { background: #f2e9ff; color: #7b2cbf; }
    .cod-row { opacity: .62; cursor: default; }
    .cod-row .radio-wrap { background: #f4f4f4; }
    .cod-tag {
        background: #fff0f0;
        color: #e53935;
        padding: 4px 7px;
        border-radius: 4px;
        font-size: .62rem;
        font-weight: 800;
        white-space: nowrap;
    }
    .price-card {
        margin: 8px 10px 0;
        border: 1px solid #e5e5e5;
        border-radius: 5px;
        padding: 12px;
    }
    .secure-note {
        margin: 8px 10px 82px;
        padding: 10px;
        border: 1px solid #dcefe1;
        border-radius: 5px;
        background: #fbfffc;
        color: #198754;
        text-align: center;
        font-size: .68rem;
        font-weight: 700;
    }
    .sticky-footer {
        display: block;
